<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {PositionView} from '../../api/positions'
import type {Instrument} from '../../api/market'
import {positionInput} from './positionInput'
import {validStock} from '../../router/listContext'
const props=defineProps<{editing:PositionView|null;instruments:Instrument[];disabled:boolean}>()
const emit=defineEmits<{save:[input:{instrumentId:string;quantity:string;averageCost:string}];cancel:[];dirtyChange:[dirty:boolean]}>()
const stock=ref(''),quantity=ref('1'),cost=ref(''),error=ref('')
watch(()=>props.editing?.positionId,id=>{stock.value=props.editing?.instrumentId||'';quantity.value=props.editing?.quantity||'1';cost.value=props.editing?.averageCost||'';error.value='';void id},{immediate:true})
const dirty=computed(()=>stock.value!==(props.editing?.instrumentId||'')||
 quantity.value!==(props.editing?.quantity||'1')||cost.value!==(props.editing?.averageCost||''))
watch(dirty,value=>emit('dirtyChange',value),{immediate:true})
const options=computed(()=>props.editing?[{instrumentId:props.editing.instrumentId,displayName:props.editing.instrumentId,displayNameVerified:true}]:props.instruments)
function save(){error.value='';try{const input=positionInput({quantity:quantity.value,averageCost:cost.value});if(!validStock(stock.value))throw new Error('请先选择一只已核验的股票');emit('save',{instrumentId:stock.value,...input})}catch(e){error.value=(e as Error).message}}
</script>
<template><form class="position-form" @submit.prevent="save"><h2>{{editing?'修改当前持仓':'新增持仓'}}</h2><p v-if="editing" class="hint small">记录版本 {{editing.revision}}；修改的是当前数量与平均成本。</p><div class="fields"><label>股票<select v-model="stock" data-test="position-stock" aria-label="股票" :disabled="disabled||!!editing"><option value="">请选择股票</option><option v-for="item in options" :key="item.instrumentId" :value="item.instrumentId" :disabled="!item.displayNameVerified||!validStock(item.instrumentId)">{{item.displayName}} · {{item.instrumentId}}{{validStock(item.instrumentId)?'':' · 暂不支持持仓'}}</option></select></label><label>持仓股数<input v-model="quantity" data-test="position-quantity" aria-label="持仓股数" inputmode="numeric" maxlength="19" :disabled="disabled"/></label><label>平均成本（元）<input v-model="cost" data-test="position-cost" aria-label="平均成本（元）" inputmode="decimal" maxlength="30" :disabled="disabled"/></label></div><div v-if="editing&&dirty" class="draft-preview" aria-label="待保存的持仓修改"><strong>待保存的修改</strong><div><span>原股数 {{editing.quantity}}</span><span>新股数 {{quantity||'未填写'}}</span></div><div><span>原平均成本 {{editing.averageCost}} 元</span><span>新平均成本 {{cost?cost+' 元':'未填写'}}</span></div></div><p class="hint small">支持非整手股数与零成本。数量和成本请依据本人记录填写；费用及公司行为变化需自行核对。</p><p v-if="error" role="alert">{{error}}</p><div class="actions"><button type="submit" class="primary" data-test="position-save" :disabled="disabled">{{editing?'保存修改':'保存持仓'}}</button><button v-if="editing" type="button" :disabled="disabled" @click="emit('cancel')">取消编辑</button></div></form></template>
<style scoped>.position-form h2{margin:0 0 16px}.fields{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:16px}.fields label{display:flex;flex-direction:column;gap:8px}.fields input,.fields select{width:100%;min-height:44px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;color:var(--ink);font:inherit;background:#fff}.draft-preview{margin-top:12px;padding:10px 12px;border-inline-start:3px solid var(--accent);background:var(--canvas);overflow-wrap:anywhere}.draft-preview div{display:flex;flex-wrap:wrap;gap:4px 14px}.actions{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;min-height:44px;padding:8px 18px;border:1px solid var(--border);border-radius:8px;background:#fff;color:var(--ink);cursor:pointer}.primary{background:var(--accent);color:white}button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:700px){.fields{grid-template-columns:1fr}}</style>
